export const SITE_HTML = "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>大模型 Key 可用性测试台</title>\n<style>\n  :root, body.dark {\n    --bg:#0f1115; --panel:#171a21; --panel2:#1f242d; --text:#e6e6e6;\n    --muted:#9aa0aa; --border:#2a2f3a; --ok:#3fb950; --bad:#f85149;\n    --warn:#d29922; --accent:#58a6ff; --chip:#222833;\n  }\n  body.light {\n    --bg:#ffffff; --panel:#f6f8fa; --panel2:#eef1f4; --text:#1f2328;\n    --muted:#656d76; --border:#d0d7de; --ok:#1a7f37; --bad:#cf222e;\n    --warn:#9a6700; --accent:#0969da; --chip:#e7ebef;\n  }\n  * { box-sizing:border-box; }\n  body {\n    margin:0; background:var(--bg); color:var(--text);\n    font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;\n    font-size:14px; line-height:1.5;\n  }\n  header {\n    display:flex; align-items:center; justify-content:space-between;\n    padding:14px 20px; border-bottom:1px solid var(--border); background:var(--panel);\n    position:sticky; top:0; z-index:10;\n  }\n  header h1 { font-size:16px; margin:0; font-weight:600; }\n  .wrap { max-width:1100px; margin:0 auto; padding:20px; }\n  textarea {\n    width:100%; min-height:160px; background:var(--panel2); color:var(--text);\n    border:1px solid var(--border); border-radius:8px; padding:12px;\n    font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace; font-size:13px; resize:vertical;\n  }\n  /* 顶部左右两栏：粘贴框 + 运行日志 */\n  .topRow { display:flex; gap:14px; align-items:stretch; margin:14px 0 0; }\n  .topRow > .col { flex:1 1 50%; min-width:0; display:flex; flex-direction:column; }\n  .topColLabel { font-size:12px; color:var(--muted); margin-bottom:6px; font-weight:600; letter-spacing:.5px; }\n  .topColLabel .badge { display:inline-block; background:var(--accent); color:#fff; padding:1px 6px; border-radius:4px; font-size:10px; margin-left:6px; font-weight:500; vertical-align:1px; }\n  @media (max-width: 760px) { .topRow { flex-direction:column; } .topRow > .col { flex:1 1 auto; } }\n  .inputArea { flex:1; min-height:200px; max-height:360px; }\n  .toolbar { display:flex; flex-wrap:wrap; align-items:center; gap:8px; margin:14px 0; }\n  .proxyToggle { display:inline-flex; align-items:center; gap:5px; font-size:13px; color:var(--text2); cursor:pointer; user-select:none; }\n  .proxyToggle input { accent-color:var(--accent); }\n  .proxyState { font-size:12px; }\n  .proxyState.ok { color:#3fb950; }\n  .proxyState.bad { color:#f85149; }\n  /* CORS 方案面板（紧凑 + 可折叠） */\n  .corsPanel { margin:14px 0 4px; border:1px solid var(--border); border-radius:10px; background:var(--panel); overflow:hidden; }\n  .corsHead { display:flex; align-items:center; justify-content:space-between; padding:9px 12px; cursor:pointer; user-select:none; }\n  .corsHead:hover { background:var(--panel2); }\n  .corsTitle { font-weight:600; font-size:13px; display:flex; align-items:center; gap:8px; }\n  .corsCur { font-size:12px; color:var(--muted); font-weight:400; }\n  .corsChevron { font-size:12px; color:var(--muted); transition:transform .18s; }\n  .corsPanel.collapsed .corsChevron { transform:rotate(-90deg); }\n  .corsBody { padding:0 12px 12px; }\n  .corsPanel.collapsed .corsBody { display:none; }\n  .corsRadios { display:flex; flex-wrap:wrap; gap:6px 16px; }\n  .corsRadios label, .corsRadios2 label { cursor:pointer; user-select:none; font-size:12px; }\n  .corsRadios input, .corsRadios2 input { accent-color:var(--accent); margin-right:4px; }\n  .corsDetail { margin-top:8px; }\n  .corsCard { background:var(--panel2); border:1px solid var(--border); border-radius:8px; padding:10px; }\n  .corsSub { font-size:12px; margin-bottom:6px; }\n  .corsSub a, .corsHint a { color:var(--accent); }\n  .corsStep { margin:4px 0 4px 18px; font-size:12px; }\n  .corsStep li { margin:3px 0; }\n  .corsStep a { color:var(--accent); }\n  .corsCode { background:var(--bg); border:1px solid var(--border); border-radius:6px; padding:8px; font-family:ui-monospace,monospace; font-size:11px; white-space:pre-wrap; margin:5px 0; color:var(--text); }\n  .corsField { font-size:12px; margin:6px 0; }\n  .corsField input { background:var(--panel2); color:var(--text); border:1px solid var(--border); border-radius:6px; padding:5px 7px; font-size:11px; font-family:ui-monospace,monospace; }\n  .corsRadios2 { display:flex; flex-wrap:wrap; gap:12px; margin:6px 0; }\n  .corsHint { font-size:11px; color:var(--muted); margin-top:6px; }\n  .risk { font-size:11px; border-radius:6px; padding:7px 9px; margin-top:6px; line-height:1.6; }\n  .risk.warn { background:rgba(210,153,34,.12); border:1px solid var(--warn); color:var(--warn); }\n  .risk.danger { background:rgba(248,81,73,.12); border:1px solid var(--bad); color:var(--bad); font-weight:600; }\n  button {\n    background:var(--panel2); color:var(--text); border:1px solid var(--border);\n    border-radius:7px; padding:7px 13px; cursor:pointer; font-size:13px; transition:.15s;\n  }\n  button:hover { border-color:var(--accent); }\n  button.primary { background:var(--accent); color:#fff; border-color:var(--accent); }\n  button.primary:hover { filter:brightness(1.08); }\n  table { width:100%; border-collapse:collapse; margin-top:6px; background:var(--panel); border-radius:8px; overflow:hidden; }\n  th, td { text-align:left; padding:9px 10px; border-bottom:1px solid var(--border); vertical-align:middle; }\n  th { background:var(--panel2); color:var(--muted); font-weight:600; font-size:12px; }\n  td input {\n    width:100%; background:var(--panel2); color:var(--text); border:1px solid var(--border);\n    border-radius:6px; padding:6px 8px; font-size:12px; font-family:ui-monospace,monospace;\n  }\n  .tag { display:inline-block; padding:2px 8px; border-radius:20px; font-size:11px; border:1px solid var(--border); }\n  .tag.openai { color:var(--accent); border-color:var(--accent); }\n  .tag.anthropic { color:#d29922; border-color:#d29922; }\n  .tag.unknown { color:var(--muted); }\n  .tag.ok { color:var(--ok); border-color:var(--ok); }\n  .tag.bad { color:var(--bad); border-color:var(--bad); }\n  .tag.warn { color:var(--warn); border-color:var(--warn); }\n  #entriesTable { margin-top:14px; }\n  .cards { margin-top:18px; display:grid; gap:12px; }\n  .card { background:var(--panel); border:1px solid var(--border); border-radius:10px; padding:14px; }\n  .card h3 { margin:0 0 6px; font-size:14px; display:flex; gap:8px; align-items:center; flex-wrap:wrap; }\n  .card .msg { margin:4px 0; }\n  .meta { color:var(--muted); font-size:12px; }\n  .chips { display:flex; flex-wrap:wrap; gap:6px; margin-top:8px; transition:max-height .25s ease; }\n  .chips.collapsed { max-height:78px; overflow:hidden; }\n  .chip {\n    background:var(--chip); border:1px solid var(--border); border-radius:16px;\n    padding:3px 10px; font-size:12px; cursor:pointer; font-family:ui-monospace,monospace;\n    transition:border-color .15s, background .15s;\n  }\n  .chip:hover { border-color:var(--accent); background:var(--panel2); }\n  .chip.copied { animation:chipFlash 1s ease; }\n  @keyframes chipFlash { 0% { background:var(--ok); border-color:var(--ok); color:#fff; } 100% { background:var(--chip); border-color:var(--border); color:inherit; } }\n  .chip .st { margin-left:6px; font-size:11px; }\n  .chipToggle { display:inline-block; margin-top:6px; font-size:12px; color:var(--accent); cursor:pointer; user-select:none; }\n  .chipToggle:hover { text-decoration:underline; }\n  .empty { color:var(--muted); text-align:center; padding:30px; }\n  /* freetoken 免费探测结果 */\n  .freeProbe { margin-top:8px; border-top:1px dashed var(--border); padding-top:8px; }\n  .fpTitle { font-size:12px; color:var(--muted); margin-bottom:4px; }\n  .fpList { display:flex; flex-wrap:wrap; gap:5px; }\n  .fptag { font-size:11px; padding:2px 7px; border-radius:6px; border:1px solid var(--border); font-family:ui-monospace,monospace; }\n  .fptag.ok { color:var(--ok); border-color:var(--ok); }\n  .fptag.bad { color:var(--muted); opacity:.55; text-decoration:line-through; }\n  /* log panel */\n  .logPanel { margin-top:22px; border:1px solid var(--border); border-radius:10px; overflow:hidden; }\n  .logHead { display:flex; align-items:center; justify-content:space-between; padding:9px 12px; background:var(--panel2); border-bottom:1px solid var(--border); font-size:13px; font-weight:600; }\n  .logBtns button { padding:4px 10px; font-size:12px; }\n  .logBox { max-height:280px; overflow:auto; padding:10px 12px; font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace; font-size:12px; line-height:1.7; background:var(--bg); color:var(--text2); }\n  .logBox .empty { padding:18px; }\n  .logline { white-space:pre-wrap; word-break:break-all; }\n  .log-ok { color:#3fb950; }\n  .log-err { color:#f85149; }\n  .log-warn { color:#d29922; }\n  .log-info { color:var(--text); }\n  /* modal */\n  .overlay {\n    position:fixed; inset:0; background:rgba(0,0,0,.55); display:none;\n    align-items:center; justify-content:center; z-index:50; padding:20px;\n  }\n  .overlay.show { display:flex; }\n  .modal { background:var(--panel); border:1px solid var(--border); border-radius:12px; max-width:900px; width:100%; max-height:85vh; overflow:auto; padding:18px; }\n  .modal h2 { margin:0 0 12px; font-size:16px; }\n  .modal table { font-size:12px; }\n  .modal table th, .modal table td { padding:7px 9px; }\n  /* 持续对话面板（内嵌在页面下方） */\n  /* 对话框内嵌于页面下方：聊天内容区可滚动，不遮挡下方内容 */\n  .chat-inline { position: relative; }\n  .chat-inline .chat-body {\n    min-height: 200px; max-height: min(480px, 55vh);\n    overflow-y: auto; overflow-x: hidden;\n    scroll-behavior: smooth;\n    scrollbar-width: thin; scrollbar-color: var(--border) transparent;\n  }\n  .chat-inline .chat-body::-webkit-scrollbar { width: 6px; }\n  .chat-inline .chat-body::-webkit-scrollbar-track { background: transparent; }\n  .chat-inline .chat-body::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }\n  .chat-inline .chat-body::-webkit-scrollbar-thumb:hover { background: var(--accent); }\n  /* 每条消息的复制按钮 */\n  .chat-msg { position: relative; margin: 9px 0; display: flex; }\n  .chat-msg.user { justify-content: flex-end; }\n  .chat-msg.assistant { justify-content: flex-start; }\n  .chat-bubble {\n    max-width: 82%; padding: 9px 13px; border-radius: 13px;\n    white-space: pre-wrap; word-break: break-word; font-size: 13px; line-height: 1.65;\n    position: relative;\n  }\n  .chat-msg.user .chat-bubble { background: var(--accent); color: #fff; border-bottom-right-radius: 4px; }\n  .chat-msg.assistant .chat-bubble { background: var(--panel2); color: var(--text); border: 1px solid var(--border); border-bottom-left-radius: 4px; }\n  .chat-bubble.thinking { color: var(--muted); font-style: italic; }\n  /* 气泡上的复制按钮 */\n  .chat-copy-btn {\n    position: absolute; top: 4px; right: 4px; opacity: 0;\n    width: 22px; height: 22px; border-radius: 4px;\n    background: rgba(0,0,0,.25); border: none; cursor: pointer;\n    color: inherit; font-size: 12px; line-height: 1; padding: 0;\n    display: flex; align-items: center; justify-content: center;\n    transition: opacity .15s, background .15s;\n  }\n  .chat-msg:hover .chat-copy-btn { opacity: 1; }\n  .chat-msg.user .chat-copy-btn { background: rgba(255,255,255,.25); }\n  .chat-copy-btn:hover { background: rgba(0,0,0,.45); }\n  .chat-msg.user .chat-copy-btn:hover { background: rgba(255,255,255,.45); }\n  .chat-copy-btn.copied { background: #4caf50; color: #fff; }\n  .chat-msg.user .chat-copy-btn.copied { background: #69f0ae; color: #005a2e; }\n  /* 手滚上滚时浮出的「回到底部」按钮 */\n  .scroll-bottom-btn {\n    position: absolute; bottom: 110px; right: 16px; z-index: 3;\n    width: 32px; height: 32px; border-radius: 50%;\n    background: var(--accent); color: #fff; border: none; cursor: pointer;\n    font-size: 15px; line-height: 1; display: flex; align-items: center; justify-content: center;\n    box-shadow: 0 2px 8px rgba(0,0,0,.3);\n    opacity: 0; transform: translateY(8px); pointer-events: none;\n    transition: opacity .18s ease, transform .18s ease;\n  }\n  .scroll-bottom-btn.show { opacity: 1; transform: translateY(0); pointer-events: auto; }\n  .scroll-bottom-btn:hover { filter: brightness(1.12); }\n  .chat-inline .chat-head { margin-bottom:10px; gap:10px; }\n  .chat-inline .chat-meta2 { font-size:12px; color:var(--muted); margin-top:4px; word-break:break-all; }\n  .chat-inline .chat-input { margin-top:10px; flex-wrap:wrap; align-items:flex-end; }\n  .chat-inline .chat-toolbar { display:flex; gap:8px; align-items:center; flex-wrap:wrap; margin-top:8px; }\n  .file-chips { display:flex; flex-wrap:wrap; gap:6px; margin-top:6px; min-height:0; }\n  .file-chip {\n    display:inline-flex; align-items:center; gap:6px; padding:3px 9px; border-radius:14px;\n    background:var(--panel2); border:1px solid var(--border); font-size:12px;\n  }\n  .file-chip img { width:18px; height:18px; object-fit:cover; border-radius:3px; }\n  .file-chip .x { cursor:pointer; color:var(--muted); }\n  .file-chip .x:hover { color:var(--bad); }\n  .chat-inline .chat-input #chatModel { width:160px; flex:none; }\n  .chat-inline .chat-input textarea { flex:1; min-height:48px; max-height:160px; }\n  .file-btn { display:inline-flex; gap:5px; align-items:center; padding:6px 12px; border:1px dashed var(--border); border-radius:8px; background:var(--panel2); color:var(--text); cursor:pointer; font-size:12px; }\n  .file-btn:hover { border-color:var(--accent); color:var(--accent); }\n  .chat-msg .chat-bubble img { max-width:220px; max-height:220px; border-radius:8px; margin-top:4px; display:block; }\n  .chat-msg .chat-bubble .file-attached { display:block; margin-top:5px; padding:4px 8px; background:var(--bg); border:1px solid var(--border); border-radius:6px; font-size:12px; color:var(--muted); word-break:break-all; }\n  .chat-msg.user .chat-bubble .file-attached { background:rgba(255,255,255,.18); border-color:rgba(255,255,255,.25); color:#fff; }\n  .chatBtn { padding:5px 10px; font-size:12px; background:var(--accent); color:#fff; border-color:var(--accent); }\n  .chatBtn:hover { filter:brightness(1.08); }\n  .export-opts { display:flex; gap:14px; flex-wrap:wrap; margin-bottom:12px; align-items:center; }\n  .export-opts label { display:flex; gap:5px; align-items:center; color:var(--muted); font-size:13px; }\n  .toast {\n    position:fixed; bottom:20px; left:50%; transform:translateX(-50%);\n    background:var(--panel2); border:1px solid var(--border); color:var(--text);\n    padding:10px 16px; border-radius:8px; display:none; z-index:60; font-size:13px;\n  }\n  .toast.show { display:block; }\n  .hint { color:var(--muted); font-size:12px; margin-top:6px; }\n  code.k { font-family:ui-monospace,monospace; }\n</style>\n</head>\n<body class=\"dark\">\n<header>\n  <h1>🔑 大模型 Key 可用性测试台</h1>\n  <button id=\"themeBtn\" title=\"切换明暗\">🌙 暗色</button>\n</header>\n\n<div class=\"wrap\">\n  <div class=\"topRow\">\n    <div class=\"col\">\n      <div class=\"topColLabel\">📋 粘贴框<span class=\"badge\">粘贴即解析</span></div>\n      <textarea id=\"input\" class=\"inputArea\" placeholder=\"在此粘贴任意组合的 接口地址 / API Key / 模型ID（支持多组，空行分隔）。\n例如：\nhttps://api.openai.com/v1\nsk-xxxxxxx\ngpt-4o\n\nhttps://api.anthropic.com\nsk-ant-xxxx\nclaude-3-5-sonnet-20241022\n\nhttps://my-proxy.com/v1\nsk-aaa\nsk-bbb\nsk-ccc\"></textarea>\n    </div>\n    <div class=\"col\">\n      <div class=\"topColLabel\">📜 运行日志<span class=\"badge\" id=\"logBadge\">实时</span></div>\n      <div class=\"logPanel\">\n        <div class=\"logHead\">\n          <span>运行日志</span>\n          <span class=\"logBtns\">\n            <button id=\"logClear\">清空</button>\n            <button id=\"logCopy\">复制日志</button>\n          </span>\n        </div>\n        <div class=\"logBox\" id=\"logBox\"><div class=\"empty\">暂无日志（解析或测试时自动记录）</div></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"toolbar\">\n    <button class=\"primary\" id=\"parseBtn\">解析</button>\n    <button id=\"selAll\">全选</button>\n    <button id=\"selNone\">反选</button>\n    <button class=\"primary\" id=\"testAll\">测试全部</button>\n    <button id=\"testSel\">测试选中</button>\n    <button id=\"testList\">测试模型列表</button>\n    <button id=\"clearBtn\">清空</button>\n    <button id=\"exportBtn\">导出 ▾</button>\n  </div>\n  <div class=\"hint\" id=\"parseHint\">粘贴后自动解析；支持 sk-/sk-ant-/AIza/tf_ 等格式密钥。表格内字段可手动修改后测试。默认全部勾选。</div>\n\n  <div id=\"entriesTable\"></div>\n  <div class=\"cards\" id=\"results\"><div class=\"empty\">尚无测试结果</div></div>\n\n  <div id=\"chatHost\"></div>\n\n  <!-- CORS 解决方案（已移至页面最底部，下方） -->\n  <div class=\"corsPanel collapsed\" id=\"corsPanel\" style=\"margin-top:18px;\">\n    <div class=\"corsHead\" id=\"corsHead\" title=\"点击展开/折叠\">\n      <span class=\"corsTitle\">🌐 CORS 解决方案（四选一，单选）<span class=\"corsCur\" id=\"corsCur\"></span></span>\n      <span class=\"corsChevron\" id=\"corsChevron\">▾</span>\n    </div>\n    <div class=\"corsBody\" id=\"corsBody\">\n      <div class=\"corsRadios\">\n        <label><input type=\"radio\" name=\"corsMethod\" value=\"A\"> A. 浏览器扩展解锁 CORS</label>\n        <label><input type=\"radio\" name=\"corsMethod\" value=\"B\"> B. 带参数启动浏览器</label>\n        <label><input type=\"radio\" name=\"corsMethod\" value=\"C\"> C. 公共 CORS 代理</label>\n        <label><input type=\"radio\" name=\"corsMethod\" value=\"D\"> D. 运行 proxy.js（本地 / 云端）</label>\n      </div>\n      <div class=\"corsDetail\" id=\"corsDetail\"></div>\n    </div>\n  </div>\n</div>\n\n<!-- Export modal -->\n<div class=\"overlay\" id=\"exportOverlay\">\n  <div class=\"modal\">\n    <h2>导出可用模型与 Key</h2>\n    <div class=\"export-opts\">\n      <label>范围：\n        <select id=\"expScope\">\n          <option value=\"ok\">仅可用</option>\n          <option value=\"all\">全部</option>\n        </select>\n      </label>\n      <label><input type=\"checkbox\" id=\"expFullKey\"> 显示完整 Key</label>\n      <label><input type=\"checkbox\" id=\"expModels\" checked> 含模型列表</label>\n    </div>\n    <div id=\"exportPreview\"></div>\n    <div class=\"toolbar\" style=\"margin-top:14px;\">\n      <button id=\"copyMd\">复制 Markdown</button>\n      <button id=\"dlMd\">下载 .md</button>\n      <button id=\"dlJson\">下载 .json</button>\n      <button id=\"dlTxt\">下载 .txt</button>\n      <button id=\"closeExport\">关闭</button>\n    </div>\n  </div>\n</div>\n\n<!-- 内嵌聊天面板模板（点击\"对话\"后由 openChat 注入到 chatHost 中） -->\n<template id=\"chatTpl\">\n  <div class=\"chat-inline\" id=\"chatInline\">\n    <button class=\"scroll-bottom-btn\" id=\"scrollBottomBtn\" title=\"滚到底部\">↓</button>\n    <div class=\"chat-head\">\n      <div>\n        <strong>💬 网页持续对话</strong>\n        <div class=\"chat-meta2\" id=\"chatMeta\"></div>\n      </div>\n      <button id=\"chatClose\">关闭 ⨯</button>\n    </div>\n    <div class=\"chat-body\" id=\"chatBody\"></div>\n    <div class=\"chat-input\">\n      <input id=\"chatModel\" placeholder=\"模型ID\" list=\"\">\n      <textarea id=\"chatText\" placeholder=\"输入消息，Enter 发送，Shift+Enter 换行\"></textarea>\n      <button class=\"primary\" id=\"chatSend\">发送</button>\n    </div>\n    <div class=\"chat-toolbar\">\n      <label class=\"file-btn\" id=\"chatFileLabel\" title=\"可上传图片/PDF/文本文件，图片会被作为 image_url 发送\">\n        📎 上传文件\n        <input type=\"file\" id=\"chatFile\" multiple style=\"display:none\" accept=\"image/*,.pdf,.txt,.md,.csv,.json,.xml,.html,.js,.ts,.py,.java,.c,.cpp,.go,.rs,.sh,.yaml,.yml,.log,.doc,.docx,.xls,.xlsx,.ppt,.pptx\">\n      </label>\n      <span class=\"hint\" id=\"chatFileInfo\" style=\"margin:0;\">未选择文件</span>\n      <span class=\"chat-meta2\" id=\"chatStatus\" style=\"margin-left:auto;\"></span>\n    </div>\n    <div class=\"file-chips\" id=\"fileChips\"></div>\n  </div>\n</template>\n\n<div class=\"toast\" id=\"toast\"></div>\n\n<script>\n\"use strict\";\nlet entries = [];\nconst results = {}; // id -> {status, vendor, models, message, latency, modelStatus:{}}\n\n/* ---------- 工具 ---------- */\nfunction $(id){ return document.getElementById(id); }\nfunction toast(msg){ const t=$('toast'); t.textContent=msg; t.classList.add('show'); setTimeout(()=>t.classList.remove('show'),2200); }\nfunction maskKey(k){ if(!k) return ''; return k.length>10 ? k.slice(0,6)+'••••'+k.slice(-4) : '••••'+k; }\nfunction esc(s){ return String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c])); }\n\n/* ---------- 运行日志 ---------- */\nconst logLines=[];\nfunction log(msg, type){\n  const t=new Date().toLocaleTimeString('zh-CN',{hour12:false});\n  const line='['+t+'] '+(type?'['+type+'] ':'')+msg;\n  logLines.push(line);\n  const box=$('logBox');\n  if(box){\n    const ph=box.querySelector('.empty'); if(ph) ph.remove();\n    const p=document.createElement('div'); p.className='logline'+(type?' log-'+type:''); p.textContent=line; box.appendChild(p); box.scrollTop=box.scrollHeight;\n  }\n}\n\nfunction fetchWithTimeout(url, opts, ms=15000){\n  const c=new AbortController(); const t=setTimeout(()=>c.abort(),ms);\n  return fetch(url, Object.assign({signal:c.signal}, opts)).finally(()=>clearTimeout(t));\n}\n// 网络兼容自动降级：直连失败且本机 proxy.js 在线时，自动改走 D 代理（等价 Chatbox「改善网络兼容性」）\n// 健康检查结果缓存 30s，避免每次失败都重测\nlet __proxyHealth={ok:false, ts:0};\nasync function compatFetch(url, opts, ms=15000){\n  try{\n    return await fetchWithTimeout(url, opts, ms);\n  }catch(e){\n    // 已走代理（C/D）或本就没开网络兼容：不降级，直接抛出\n    if(corsMethod==='C' || corsMethod==='D') throw e;\n    const now=Date.now();\n    if(now-__proxyHealth.ts > 30000){\n      try{\n        const hr=await fetchWithTimeout((proxyBase||'http://localhost:8787')+'/health',{cache:'no-store'}, 1500);\n        __proxyHealth={ok:hr.ok, ts:now};\n      }catch(e2){ __proxyHealth={ok:false, ts:now}; }\n    }\n    if(__proxyHealth.ok){\n      log('⚡ 网络兼容：直连被浏览器拦截，已自动改走本机 proxy.js 重试', 'warn');\n      const proxied=(proxyBase||'http://localhost:8787')+'/?url='+encodeURIComponent(url);\n      return await fetchWithTimeout(proxied, opts, ms);\n    }\n    throw e;\n  }\n}\n\n/* ---------- CORS 解决方案（4 选 1） ---------- */\nlet corsMethod=null;                  // 'A' | 'B' | 'C' | 'D' | null\nlet proxyDeploy=null;                 // D 子选项：'local' | 'cf' | 'vercel' | 'render'\nlet proxyBase='http://localhost:8787';// D 实际代理地址（本地或云端部署地址）\nlet publicProxyBase='';               // C 公共代理前缀（到 ?url= 之前）\nconst CORS_LABEL={A:'扩展',B:'参数启动',C:'公共代理',D:'本地/云代理'};\nlet corsCollapsed=true;             // 默认折叠，节省显示空间\ntry{ const c=localStorage.getItem('llmTesterCorsCollapsed'); if(c!==null) corsCollapsed=(c==='1'); }catch(e){}\nfunction setCorsCollapsed(c){\n  corsCollapsed=c;\n  const p=$('corsPanel'); if(!p) return;\n  p.classList.toggle('collapsed', c);\n  try{ localStorage.setItem('llmTesterCorsCollapsed', c?'1':'0'); }catch(e){}\n}\nfunction updateCorsCur(){\n  const el=$('corsCur'); if(!el) return;\n  el.textContent = corsMethod ? ('（当前：'+CORS_LABEL[corsMethod]+'）') : '（未选）';\n}\nfunction corsLabel(){ return CORS_LABEL[corsMethod]||'未选'; }\nfunction usingProxy(){ return corsMethod==='C' || corsMethod==='D'; }\nfunction proxyWrap(url){\n  if(corsMethod==='A' || corsMethod==='B') return url;                       // 直连（靠扩展/参数启动放行 CORS）\n  if(corsMethod==='C') return (publicProxyBase||'https://corsproxy.io/?url=')+encodeURIComponent(url);\n  if(corsMethod==='D') return (proxyBase||'http://localhost:8787')+'/?url='+encodeURIComponent(url);\n  return url;\n}\nasync function checkProxy(){\n  const st=$('corsStatus'); if(!st) return false;\n  if(corsMethod!=='D'){ st.textContent=''; st.className='proxyState'; return false; }\n  try{\n    const r=await fetch(proxyBase+'/health',{cache:'no-store'});\n    if(r.ok){ st.textContent='代理在线'; st.className='proxyState ok'; return true; }\n  }catch(e){}\n  st.textContent='代理未启动/不可达'; st.className='proxyState bad'; return false;\n}\n\n/* 渲染 CORS 方案详情 */\nfunction renderCorsDetail(){\n  const box=$('corsDetail');\n  if(!corsMethod){ box.innerHTML='<div class=\"corsHint\">请选择一种方案。A/B 最安全（key 直连目标，不经第三方）；C/D 会把请求经代理转发，详见各自风险提示。<br>💡 提示：Chatbox 网页版的「改善网络兼容性」开关本质就是用代理中继绕过浏览器 CORS——在本工具中对应方案 <b>D 本地 proxy.js</b>（推荐）或 <b>C 公共代理</b>。直连不通时优先切到这两项。</div>'; return; }\n  let h='';\n  if(corsMethod==='A'){\n    h=`<div class=\"corsCard\">\n      <div class=\"corsSub\">说明：安装浏览器扩展放行跨域响应头，页面<b>直接连接目标 API，key 不经过任何第三方</b>。最干净。</div>\n      <ol class=\"corsStep\">\n        <li>在扩展商店安装其一：\n          <a href=\"https://chrome.google.com/webstore/search/cors%20unblock\" target=\"_blank\" rel=\"noopener\">Chrome：CORS Unblock</a> ｜\n          <a href=\"https://chrome.google.com/webstore/search/allow%20cors%20access%20control\" target=\"_blank\" rel=\"noopener\">Allow CORS: Access-Control-Allow-Origin</a> ｜\n          <a href=\"https://microsoftedge.microsoft.com/addons/search/cors%20unblock\" target=\"_blank\" rel=\"noopener\">Edge 加载项</a>\n        </li>\n        <li>启用扩展，点击图标开启（部分需刷新页面生效）。</li>\n        <li>本页保持「不勾代理」，直接点「测试全部」。</li>\n      </ol>\n      <div class=\"risk warn\">⚠️ 风险：扩展会改写所有网站的跨域响应头。仅在测试期间开启，用完关闭；不要在不信任的扩展里粘贴密钥。</div>\n    </div>`;\n  } else if(corsMethod==='B'){\n    h=`<div class=\"corsCard\">\n      <div class=\"corsSub\">说明：用参数启动一个<b>临时浏览器实例</b>，关闭其同源策略后直接打开本 HTML。key 直连目标，不经第三方。</div>\n      <div class=\"corsCode\"># Windows（路径换成你本机 Chrome）\nchrome.exe --user-data-dir=\"C:\\\\temp\\\\cors-test\" --disable-web-security\n\n# macOS\n/Applications/Google\\\\ Chrome.app/Contents/MacOS/Google\\\\ Chrome --user-data-dir=/tmp/cors-test --disable-web-security</div>\n      <ol class=\"corsStep\">\n        <li>关闭所有 Chrome 窗口，用上面命令重新启动。</li>\n        <li>在打开的浏览器里拖入本 HTML 文件，然后测试。</li>\n      </ol>\n      <div class=\"risk warn\">⚠️ 风险：该实例关闭了安全策略，整个浏览器临时处于不安全状态。仅用于测试，不要在此实例登录重要账号；测试完正常重启浏览器。</div>\n    </div>`;\n  } else if(corsMethod==='C'){\n    h=`<div class=\"corsCard\">\n      <div class=\"corsSub\">说明：请求经<b>第三方公共代理</b>转发，绕过浏览器跨域。请填入公共代理地址（前缀，到 <code class=\"k\">?url=</code> 之前）。</div>\n      <div class=\"corsField\">公共代理地址：<input id=\"publicProxyInput\" value=\"${esc(publicProxyBase)}\" placeholder=\"例如 https://corsproxy.io/?url=\" style=\"width:340px;\"></div>\n      <div class=\"risk danger\">🚫 强烈不推荐用于真实密钥：你的 key 会经过第三方公共服务器，可能被记录/泄露；公共代理常不稳定、限流、甚至中途注入。仅临时验证用，用完即弃。</div>\n      <div class=\"corsHint\">常用公共代理（稳定性各异，自行甄别）：corsproxy.io、api.allorigins.win/raw?url=、thingproxy.freeboard.io</div>\n    </div>`;\n  } else if(corsMethod==='D'){\n    h=`<div class=\"corsCard\">\n      <div class=\"corsSub\">说明：运行 proxy.js（与 HTML 同目录的 Node 服务）转发请求。<b>本地运行最安全（key 不出本机）</b>；也可部署到云端（key 会经过你部署的平台）。</div>\n      <div class=\"corsRadios2\">\n        <label><input type=\"radio\" name=\"proxyDeploy\" value=\"local\" ${proxyDeploy==='local'?'checked':''}> ① 本地运行（推荐）</label>\n        <label><input type=\"radio\" name=\"proxyDeploy\" value=\"cf\" ${proxyDeploy==='cf'?'checked':''}> ② Cloudflare Workers</label>\n        <label><input type=\"radio\" name=\"proxyDeploy\" value=\"vercel\" ${proxyDeploy==='vercel'?'checked':''}> ③ Vercel / Netlify</label>\n        <label><input type=\"radio\" name=\"proxyDeploy\" value=\"render\" ${proxyDeploy==='render'?'checked':''}> ④ Render / Railway / Fly.io</label>\n      </div>\n      <div id=\"deployDetail\"></div>\n      <div class=\"proxyState\" id=\"corsStatus\"></div>\n    </div>`;\n  }\n  box.innerHTML=h;\n  const pub=$('publicProxyInput'); if(pub) pub.oninput=()=>{ publicProxyBase=pub.value.trim(); };\n  const dp=box.querySelectorAll('input[name=proxyDeploy]'); dp.forEach(r=>r.onchange=()=>{ proxyDeploy=r.value; onDeployChange(); });\n  if(corsMethod==='D' && proxyDeploy) renderDeployDetail();\n  updateCorsCur();\n}\nfunction onDeployChange(){\n  if(proxyDeploy==='local'){ proxyBase='http://localhost:8787'; }\n  else if(proxyDeploy==='cf'){ proxyBase='https://KeyCheck.hhxx.eu.org/proxy'; }\n  renderCorsDetail();\n  checkProxy();\n}\nfunction renderDeployDetail(){\n  const box=$('deployDetail'); if(!box) return;\n  let h='';\n  if(proxyDeploy==='local'){\n    h=`<ol class=\"corsStep\">\n        <li>安装 Node.js（<a href=\"https://nodejs.org\" target=\"_blank\" rel=\"noopener\">nodejs.org</a>，LTS 即可）。</li>\n        <li>在本 HTML 同目录打开命令行，运行：<code class=\"k\">node proxy.js</code></li>\n        <li>看到「LLM 测试代理已启动: http://localhost:8787」后保持窗口开着。</li>\n        <li>本面板选 D + 本地，右侧状态显示「代理在线」即可测试。</li>\n      </ol>\n      <div class=\"corsHint\">proxy.js 下载/安装包指引稍后补充（下载地址待完善）。</div>\n      <div class=\"risk warn\">⚠️ 需保持命令行窗口运行；key 仅在本机转发，最安全。</div>`;\n  } else if(proxyDeploy==='cf'){\n    h=`<div class=\"corsSub\">把代理改成 Cloudflare Worker 部署：免费、边缘节点、自带 HTTPS。本仓库 <code class=\"k\">worker/worker.js</code> 已按「同域 /proxy 反代 + / 返回页面」写好，部署后地址即 <code class=\"k\">https://KeyCheck.hhxx.eu.org/proxy</code>。</div>\n      <div class=\"corsField\">你的部署地址：<input class=\"deployUrl\" value=\"${esc(proxyBase)}\" placeholder=\"例如 https://KeyCheck.hhxx.eu.org/proxy\" style=\"width:340px;\"></div>\n      <ol class=\"corsStep\"><li>仓库根目录运行 <code class=\"k\">node deploy.mjs</code>（会读取 备忘key.txt 里的 Cloudflare 全局密钥，自动建 DNS + 部署 Worker）。</li><li>部署后上方已自动填好云端地址，状态显示「代理在线」即可测试。</li></ol>\n      <div class=\"risk danger\">🚫 风险：key 会经过 Cloudflare 及你的 Worker 服务，平台/服务可见请求与密钥。务必用<b>自己的账号</b>自建，不要把代理地址公开分享；免费层可能冷启动慢。</div>`;\n  } else if(proxyDeploy==='vercel'){\n    h=`<div class=\"corsSub\">部署为 Vercel / Netlify 的 Serverless Function（把 proxy.js 改成函数版）。</div>\n      <div class=\"corsField\">你的部署地址：<input class=\"deployUrl\" value=\"${esc(proxyBase)}\" placeholder=\"例如 https://llm-proxy.vercel.app\" style=\"width:340px;\"></div>\n      <ol class=\"corsStep\"><li><a href=\"https://vercel.com/\" target=\"_blank\" rel=\"noopener\">Vercel</a> 或 <a href=\"https://www.netlify.com/\" target=\"_blank\" rel=\"noopener\">Netlify</a> 新建项目，部署代理函数。</li><li>填入部署地址。</li></ol>\n      <div class=\"risk danger\">🚫 风险：key 经 Vercel/Netlify 平台及你的服务，平台可见。自建、勿公开地址。</div>`;\n  } else if(proxyDeploy==='render'){\n    h=`<div class=\"corsSub\">部署为 Render / Railway / Fly.io 的完整 Node 服务（最接近现在的 proxy.js）。</div>\n      <div class=\"corsField\">你的部署地址：<input class=\"deployUrl\" value=\"${esc(proxyBase)}\" placeholder=\"例如 https://llm-proxy.onrender.com\" style=\"width:340px;\"></div>\n      <ol class=\"corsStep\"><li><a href=\"https://render.com/\" target=\"_blank\" rel=\"noopener\">Render</a> / <a href=\"https://railway.app/\" target=\"_blank\" rel=\"noopener\">Railway</a> / <a href=\"https://fly.io/\" target=\"_blank\" rel=\"noopener\">Fly.io</a> 新建服务，上传 proxy.js 并部署。</li><li>填入部署地址。</li></ol>\n      <div class=\"risk danger\">🚫 风险：key 经对应平台及你的服务，平台可见。自建、勿公开地址；免费层可能休眠。</div>`;\n  }\n  box.innerHTML=h;\n  const u=box.querySelector('.deployUrl'); if(u) u.oninput=()=>{ proxyBase=u.value.trim(); checkProxy(); };\n}\n\n/* ---------- URL 归一 ---------- */\n// 支持用户粘贴「完整端点 URL」（含 /chat/completions 或 /messages），自动归一到 /v1 根\nfunction deriveEndpoints(base){\n  base=(base||'').replace(/\\/+$/,'');\n  // 已是完整 chat 端点：.../v1/chat/completions\n  let m=base.match(/^(.*\\/v1)\\/chat\\/completions$/i);\n  if(m) return { root:m[1], models:m[1]+'/models', chat:m[1]+'/chat/completions', anthropic:false };\n  // 已是完整 messages 端点（anthropic 原生）\n  m=base.match(/^(.*\\/v1)\\/messages$/i);\n  if(m) return { root:m[1], models:m[1]+'/models', chat:m[1]+'/messages', anthropic:true };\n  // 普通 base（可能不含 /v1）\n  const root=base.endsWith('/v1')?base:(base+'/v1');\n  return { root, models:root+'/models', chat:root+'/chat/completions', anthropic:false };\n}\nfunction modelUrls(base){\n  const d=deriveEndpoints(base);\n  return [d.models, d.root.replace(/\\/v1$/,'').replace(/\\/$/,'')+'/models'];\n}\nfunction chatUrl(base, vendor){\n  const d=deriveEndpoints(base);\n  if(d.anthropic) return d.chat;\n  return (vendor==='anthropic') ? d.root+'/messages' : d.root+'/chat/completions';\n}\n\n/* ---------- 解析 ---------- */\nfunction parseInput(text){\n  let blocks = text.split(/\\n\\s*\\n/).map(b=>b.trim()).filter(Boolean);\n  if(blocks.length===0 && text.trim()) blocks=[text.trim()];\n  const out=[]; let currentBase=null, idc=0;\n  const modelPrefix=/^(gpt|o[0-9]|claude|gemini|agnes|text|deepseek|qwen|moonshot|kimi|glm|yi|ling|mimo|mistral|llama|command|minimax|minimaxai|sensenova)/i;\n  for(const block of blocks){\n    const urls=[...block.matchAll(/https?:\\/\\/[^\\s\"'<>]+/g)].map(m=>m[0].replace(/\\/+$/,''));\n    const localBase=urls[0]||null;\n    if(localBase) currentBase=localBase;\n    const base=localBase||currentBase;\n    const urlSet=new Set(urls);\n    // 关键字符集放宽到包含 . + / =，避免 JWT / base64 型长 key 被按特殊字符拆成多段\n    const keyRe=/(?:sk-ant-[A-Za-z0-9_\\-.\\/+=]{8,}|sk-[A-Za-z0-9_\\-.\\/+=]{8,}|AIza[A-Za-z0-9_\\-.\\/+=]{20,}|tf[_\\-][A-Za-z0-9_\\-.\\/+=]{24,}|[A-Za-z0-9_\\-.\\/+=]{24,})/g;\n    const modelPrefixBlock=/^(gpt|o[0-9]|claude|gemini|agnes|text|deepseek|qwen|moonshot|kimi|glm|yi|ling|mimo|mistral|llama|command|minimax|minimaxai|sensenova)/i;\n    const keys=[...new Set([...block.matchAll(keyRe)].map(m=>m[0])\n      .filter(k=>!urlSet.has(k) && !urls.some(u=>u.includes(k)))\n      .filter(k=>!modelPrefixBlock.test(k)))];\n    // 去掉 URL 后再扫模型，避免把接口地址里的 \"sensenova.cn/v1\" 误当成模型 ID\n    const blockNoUrl=block.replace(/https?:\\/\\/[^\\s\"'<>]+/g,' ');\n    let models=[...blockNoUrl.matchAll(new RegExp('('+modelPrefix.source.replace(/^\\^/,'')+'[A-Za-z0-9.\\\\-_/:]*)','gi'))].map(m=>m[1]);\n    for(const m of blockNoUrl.matchAll(/(?:model|模型)\\s*[:=]\\s*([^\\s\"'<>]+)/gi)) models.push(m[1].replace(/[.,;:!?)\\]}'\"]+$/,''));\n    models=[...new Set(models.map(s=>s.trim()).filter(Boolean))];\n    if(keys.length===0) continue;\n    keys.forEach((k,idx)=>{\n      let model=null;\n      if(models.length===1) model=models[0];\n      else if(models.length>1) model=models[Math.min(idx,models.length-1)];\n      out.push({id:'e'+(idc++), base:base||'', key:k, model, selected:true, raw:block});\n    });\n  }\n  return out;\n}\n\n/* ---------- 认证头（按厂商/host 适配） ---------- */\nfunction authHeaders(base, key, vendor){\n  const h = vendor==='anthropic'\n    ? {'x-api-key':key,'anthropic-version':'2023-06-01','Content-Type':'application/json'}\n    : {'Authorization':'Bearer '+key,'Content-Type':'application/json'};\n  // 微信智能对话 OpenAI 兼容接口用 X-OPENAI-TOKEN（不用 Bearer），缺失会返回 412 前置条件失败\n  try{\n    const host=new URL(base).hostname.toLowerCase();\n    if(host.endsWith('weixin.qq.com')) h['X-OPENAI-TOKEN']=key;\n  }catch(e){}\n  return h;\n}\n\n/* ---------- 厂商探测 + 模型列表 ---------- */\nasync function fetchModels(base, key){\n  const urls=modelUrls(base);\n  let lastStatus=null;\n  for(const url of urls){\n    try{\n      const r=await compatFetch(proxyWrap(url),{\n        method:'GET',\n        headers:authHeaders(base, key, 'openai')\n      });\n      lastStatus=r.status;\n      if(r.ok){\n        const j=await r.json().catch(()=>null);\n        if(j && Array.isArray(j.data) && j.data.length){\n          let vendor='openai';\n          if(j.object==='list') vendor='openai';\n          else if(j.data[0] && j.data[0].type==='model') vendor='anthropic';\n          const models=j.data.map(m=>m.id||m.name).filter(Boolean);\n          return {ok:true, vendor, models, status:r.status};\n        }\n      }\n    }catch(e){ lastStatus=null; }\n  }\n  return {ok:false, statusCode:lastStatus, error:lastStatus?('status-'+lastStatus):'network'};\n}\n\n/* ---------- 对话测试（自动尝试多种鉴权，兼容未知 key 类型） ---------- */\nasync function chatTest(base, key, vendor, model){\n  const url=chatUrl(base, vendor);\n  const isWeixin=(()=>{ try{ return new URL(base).hostname.toLowerCase().endsWith('weixin.qq.com'); }catch(e){ return false; } })();\n  // 微信等国产 OpenAI 兼容网关要求补 stream/temperature/user 三字段，否则 412\n  const body = vendor==='anthropic'\n    ? {model, max_tokens:64, messages:[{role:'user',content:'你好'}]}\n    : isWeixin\n      ? {model, messages:[{role:'user',content:'你好'}], max_tokens:64, stream:false, temperature:0.7, user:'llm-tester'}\n      : {model, messages:[{role:'user',content:'你好'}], max_tokens:64};\n  const bodyStr=JSON.stringify(body);\n\n  // 构造鉴权方案：微信域名依次试 X-OPENAI-TOKEN → X-APPID → Bearer；其余按厂商常规\n  const variants=[];\n  if(isWeixin){\n    variants.push({name:'X-OPENAI-TOKEN', h:{'X-OPENAI-TOKEN':key,'Content-Type':'application/json'}});\n    variants.push({name:'X-APPID', h:{'X-APPID':key,'Content-Type':'application/json'}});\n    variants.push({name:'X-Api-Key', h:{'X-Api-Key':key,'Content-Type':'application/json'}});\n    variants.push({name:'Api-Key', h:{'Api-Key':key,'Content-Type':'application/json'}});\n    variants.push({name:'X-Org-Id+Bearer', h:{'Authorization':'Bearer '+key,'X-Org-Id':key,'Content-Type':'application/json'}});\n    variants.push({name:'X-User-Id+Bearer', h:{'Authorization':'Bearer '+key,'X-User-Id':key,'Content-Type':'application/json'}});\n    variants.push({name:'token-prefix', h:{'Authorization':'token '+key,'Content-Type':'application/json'}});\n    variants.push({name:'?key=query', h:{'Authorization':'Bearer '+key,'Content-Type':'application/json'}, urlSuffix:'?key='+encodeURIComponent(key)});\n    variants.push({name:'?token=query', h:{'Authorization':'Bearer '+key,'Content-Type':'application/json'}, urlSuffix:'?token='+encodeURIComponent(key)});\n  }\n  variants.push({name:'Bearer', h:{'Authorization':'Bearer '+key,'Content-Type':'application/json'}});\n  if(vendor==='anthropic') variants.push({name:'x-api-key', h:{'x-api-key':key,'anthropic-version':'2023-06-01','Content-Type':'application/json'}});\n\n  const tried=[];\n  for(const v of variants){\n    try{\n      const vUrl = v.urlSuffix ? (url+v.urlSuffix) : url;\n      // 对话测试单独用 60s 超时（默认 15s 不够 HuggingFace reasoning 类模型慢响应）\n      const r=await compatFetch(proxyWrap(vUrl),{method:'POST',headers:v.h,body:bodyStr}, 60000);\n      if(r.ok){\n        const j=await r.json().catch(()=>null);\n        let text='';\n        if(vendor==='anthropic') text=(j.content&&j.content[0]&&j.content[0].text)||'';\n        else text=(j.choices&&j.choices[0]&&j.choices[0].message&&j.choices[0].message.content)||'';\n        return {ok:true, text:text.slice(0,100), auth:v.name, tried};\n      }\n      tried.push({name:v.name, status:r.status, error:humanStatus(r.status)});\n    }catch(e){ tried.push({name:v.name, status:0, error:e.name==='AbortError'?'响应超时（>60s，模型可能在思考或服务慢）':'网络/跨域错误'}); }\n  }\n  const detail=tried.map(t=>`${t.name}→${t.error}`).join('；');\n  return {ok:false, error:detail, tried};\n}\n\nfunction humanStatus(code){\n  switch(code){\n    case 401: return '密钥无效或已过期（认证失败）';\n    case 403: return '无权限访问该资源';\n    case 404: return '接口路径不对，检查地址是否含 /v1';\n    case 429: return '请求太频繁，被限流，稍后重试';\n    default:  return '连接失败（HTTP '+code+'）';\n  }\n}\nfunction describeError(res){\n  if(res.error==='network'){\n    if(corsMethod==='A'||corsMethod==='B') return '跨域被拦或服务不可达（浏览器 CORS 限制）。对应 Chatbox「改善网络兼容性」开关：请展开下方 CORS 方案，选择 D 运行 proxy.js（推荐）或 C 公共代理后再测。';\n    if(corsMethod==='C') return '公共 CORS 代理连接失败（请确认公共代理地址正确且服务可用）。';\n    return '本地/云端代理连接失败（请确认 proxy 服务正在运行，且本页是在你本机浏览器直接打开，而非 WorkBuddy 预览）。';\n  }\n  if(res.statusCode===401) return '密钥无效或已过期（认证失败）';\n  if(res.statusCode===403) return '无权限访问该资源';\n  if(res.statusCode===404) return '接口路径不对，检查地址是否含 /v1';\n  if(res.statusCode===429) return '请求太频繁，被限流，稍后重试';\n  return '无法识别厂商或连接失败';\n}\nfunction latencyWord(ms){ return ms<800?'快':(ms<2500?'正常':'偏慢'); }\n\n/* ---------- 渲染条目表 ---------- */\nfunction renderTable(){\n  const box=$('entriesTable');\n  if(entries.length===0){ box.innerHTML=''; return; }\n  let h='<table><thead><tr><th style=\"width:34px;\">选</th><th>接口地址</th><th>API Key</th><th>模型ID</th><th style=\"width:64px;\">对话</th><th style=\"width:90px;\">厂商</th></tr></thead><tbody>';\n  let dl='';\n  for(const e of entries){\n    const vTag = results[e.id] ? results[e.id].vendor : '';\n    const vt = vTag ? `<span class=\"tag ${vTag}\">${vTag}</span>` : '<span class=\"tag unknown\">未测</span>';\n    const dlId='dl-'+e.id;\n    const opts=(results[e.id]&&results[e.id].models)?results[e.id].models.map(m=>`<option value=\"${esc(m)}\"></option>`).join(''):'';\n    h+=`<tr>\n      <td><input type=\"checkbox\" data-id=\"${e.id}\" class=\"sel\" ${e.selected?'checked':''}></td>\n      <td><input data-f=\"base\" data-id=\"${e.id}\" value=\"${esc(e.base)}\"></td>\n      <td><input data-f=\"key\" data-id=\"${e.id}\" value=\"${esc(e.key)}\"></td>\n      <td><input data-f=\"model\" data-id=\"${e.id}\" list=\"${dlId}\" value=\"${esc(e.model||'')}\" placeholder=\"可选｜可下拉选已拉取模型\"></td>\n      <td><button class=\"chatBtn\" data-id=\"${e.id}\">对话</button></td>\n      <td>${vt}</td>\n    </tr>`;\n    dl+=`<datalist id=\"${dlId}\">${opts}</datalist>`;\n  }\n  h+='</tbody></table>'+dl;\n  box.innerHTML=h;\n  box.querySelectorAll('input.sel').forEach(cb=>cb.onchange=ev=>{\n    const e=entries.find(x=>x.id===ev.target.dataset.id); if(e) e.selected=ev.target.checked;\n  });\n  box.querySelectorAll('input[data-f]').forEach(inp=>inp.oninput=ev=>{\n    const e=entries.find(x=>x.id===ev.target.dataset.id); if(e) e[ev.target.dataset.f]=ev.target.value.trim();\n  });\n  box.querySelectorAll('.chatBtn').forEach(b=>b.onclick=()=>{ openChat(b.dataset.id); /* 滚动到下方聊天面板 */\n    setTimeout(()=>{ const host=$('chatHost'); if(host) host.scrollIntoView({behavior:'smooth', block:'start'}); }, 50);\n  });\n}\n// 测试成功后把拉到的模型列表回填到该条目行下拉框（<datalist>）\nfunction populateModelDatalist(id, models){\n  const dl=document.getElementById('dl-'+id); if(!dl) return;\n  dl.innerHTML=models.map(m=>`<option value=\"${esc(m)}\"></option>`).join('');\n}\n\n/* ---------- freetokenfaucet 自动免费探测（仅该站点，其他跳过） ---------- */\nfunction isFreetoken(base){\n  try{ return new URL(base).hostname.toLowerCase().includes('freetokenfaucet.com'); }catch(e){ return false; }\n}\n// 名字像免费/试用档的模型（用于优先试探，避免把整个模型表打一遍）\nfunction looksFree(m){\n  return /free|lite|mini|flash|haiku|nano|instant|tiny|trial|zero|gratis|no[\\-_]?cost|0\\.?0*$|免|试/i.test(m||'');\n}\nfunction freeProbeHtml(r){\n  if(!r || !Array.isArray(r.freeProbe) || !r.freeProbe.length) return '';\n  const ok=r.freeProbe.filter(x=>x.ok);\n  const items=r.freeProbe.map(x=>`<span class=\"fptag ${x.ok?'ok':'bad'}\" title=\"${esc(x.ok?'可用':('失败 '+(x.status||0)+' '+(x.error||'')))}\">${esc(x.model)}${x.ok?' ✓':''}${x.remaining?(' 余'+esc(x.remaining)):''}</span>`).join('');\n  return `<div class=\"freeProbe\"><div class=\"fpTitle\">🔍 今日免费模型探测（${ok.length}/${r.freeProbe.length} 可用）</div><div class=\"fpList\">${items}</div></div>`;\n}\nasync function runFreetokenProbe(id, knownModels){\n  const e=entries.find(x=>x.id===id); if(!e) return;\n  const today=new Date().toISOString().slice(0,10);\n  const cacheKey='ftFree_'+(e.base||'ft').replace(/[^a-z0-9]/gi,'')+'_'+today;\n  let cached=null;\n  try{ cached=JSON.parse(localStorage.getItem(cacheKey)||'null'); }catch(e2){}\n  if(Array.isArray(cached)){\n    results[id].freeProbe=cached;\n    const okL=cached.filter(x=>x.ok).map(x=>x.model);\n    results[id].message+=' ｜ 今日免费探测：'+(okL.length?okL.join('、'):'暂无可用')+'（读缓存，共 '+cached.length+' 个）';\n    renderResults(); log('🔍 读取今日免费探测缓存（'+cached.length+' 个）', 'info');\n    return;\n  }\n  log('🔍 freetoken 免费探测：开始 1→2→3', 'info');\n  const candidates=new Set();\n  // 步骤1：抓官网首页，提取「免费模型」紧邻对 + 「支持的模型」全量\n  let homepageFree=[];   // 明确标\"免费\"的优先档\n  let homepageAll=[];    // 官网列出的全量模型\n  try{\n    const r=await compatFetch(proxyWrap('https://freetokenfaucet.com/'), {method:'GET', headers:{'Accept':'text/html'}}, 12000);\n    if(r.ok){\n      const html=await r.text();\n      const text=html.replace(/<script[\\s\\S]*?<\\/script>/gi,'').replace(/<style[\\s\\S]*?<\\/style>/gi,'').replace(/<[^>]+>/g,' ').replace(/\\s+/g,' ');\n      // 匹配模型 ID：字母开头，可含 数字/./- 段；如 gpt-5.6-luna / mimo-v2.5 / kimi-k2.5\n      const idRe=/\\b([a-z][a-z0-9]*(?:[-.][a-z0-9]+){1,4})\\b/gi;\n      // 1a) 紧邻\"免费\"标签的：<model> 免费 或 免费 <model>，距离 15 字内\n      const pairRe=/([a-z][a-z0-9]*(?:[-.][a-z0-9]+){1,4})[^\\n]{0,15}?免费|免费[^\\n]{0,15}?([a-z][a-z0-9]*(?:[-.][a-z0-9]+){1,4})/gi;\n      let m;\n      while((m=pairRe.exec(text))){\n        const id=(m[1]||m[2]||'').toLowerCase();\n        if(id && modelPrefix.test(id)) homepageFree.push(id);\n      }\n      // 1b) 全部匹配 + 厂商白名单过滤\n      while((m=idRe.exec(text))){\n        const id=(m[1]||'').toLowerCase();\n        if(modelPrefix.test(id)) homepageAll.push(id);\n      }\n      homepageFree=[...new Set(homepageFree)];\n      homepageAll=[...new Set(homepageAll)];\n      homepageFree.forEach(x=>candidates.add(x));   // 免费档入候选\n      homepageAll.forEach(x=>candidates.add(x));    // 全量补全\n      log('🔍 步骤1 首页抓取完成：免费 '+homepageFree.length+' 个｜全量 '+homepageAll.length+' 个'+(homepageFree.length?('｜今日免费：'+homepageFree.join('、')):''), 'info');\n    } else log('🔍 步骤1 首页返回状态 '+r.status, 'warn');\n  }catch(err){ log('🔍 步骤1 首页抓取失败（可能需代理）：'+err.message, 'warn'); }\n  // 步骤2：GET /v1/models（即使 key 失效也试），全量入库\n  let listModels=[];\n  try{\n    for(const u of modelUrls(e.base)){\n      try{\n        const r=await compatFetch(proxyWrap(u), {method:'GET', headers:authHeaders(e.base, e.key, 'openai')});\n        if(r.ok){ const j=await r.json().catch(()=>null); if(j && Array.isArray(j.data)){ listModels=j.data.map(x=>x.id||x.name).filter(Boolean); break; } }\n      }catch(e3){}\n    }\n  }catch(e3){}\n  listModels.forEach(m=>candidates.add(m));\n  if(knownModels) knownModels.forEach(m=>candidates.add(m));\n  log('🔍 步骤2 累计候选 '+candidates.size+' 个', 'info');\n  // 步骤3 优先顺序：①首页明确标\"免费\"的 → ②用户填的模型 → ③名称像免费档的 → ④兜底全部\n  const freeSet=new Set(homepageFree);\n  let probe=[];\n  homepageFree.forEach(m=>{ if(!probe.includes(m)) probe.push(m); });\n  if(e.model && !probe.includes(e.model)) probe.push(e.model);\n  [...candidates].filter(m=>!freeSet.has(m) && m!==e.model && looksFree(m)).forEach(m=>{ if(!probe.includes(m)) probe.push(m); });\n  if(probe.length===0) probe=[...candidates].slice(0,40);\n  else if(probe.length>40) probe=probe.slice(0,40);\n  log('🔍 步骤3 优先列表：'+probe.join(' / '), 'info');\n  // 步骤3：每个候选 POST max_tokens:1 试探，读 x-ratelimit 剩余额度\n  const out=[]; const url=chatUrl(e.base,'openai');\n  for(const m of probe){\n    try{\n      const r=await compatFetch(proxyWrap(url), {method:'POST',\n        headers:{'Authorization':'Bearer '+e.key,'Content-Type':'application/json'},\n        body:JSON.stringify({model:m, messages:[{role:'user',content:'hi'}], max_tokens:1})}, 8000);\n      const remaining=r.headers.get('x-ratelimit-remaining-requests')||r.headers.get('x-ratelimit-remaining-tokens')||r.headers.get('x-quota-remaining')||'';\n      out.push({model:m, ok:r.ok, status:r.status, remaining, error:r.ok?null:((await r.text().catch(()=>'')||'').slice(0,80))});\n    }catch(err){ out.push({model:m, ok:false, status:0, error:'网络错误'}); }\n  }\n  try{ localStorage.setItem(cacheKey, JSON.stringify(out)); }catch(e4){}\n  results[id].freeProbe=out;\n  const okList=out.filter(x=>x.ok).map(x=>x.model+(x.remaining?`(${x.remaining})`:''));\n  results[id].message+=' ｜ 今日免费探测：'+(okList.length?okList.join('、'):'暂无可用')+'（共测 '+out.length+' 个）';\n  renderResults();\n  log('🔍 步骤3 完成：可用 '+(out.filter(x=>x.ok).length)+'/'+out.length, 'info');\n}\n\n/* ---------- 渲染结果卡 ---------- */\nfunction renderResults(){\n  const box=$('results');\n  const ids=Object.keys(results);\n  if(ids.length===0){ box.innerHTML='<div class=\"empty\">尚无测试结果</div>'; return; }\n  let h='';\n  for(const id of ids){\n    const e=entries.find(x=>x.id===id); const r=results[id]; if(!e) continue;\n    const stClass = r.status==='ok'?'ok':(r.status==='warn'?'warn':'bad');\n    const stText = r.status==='ok'?'可用':(r.status==='warn'?'异常':'不可用');\n    let chips='';\n    if(r.models && r.models.length){\n      // 超过 3 行（每行约 4-5 个 chip，即 > 12 个）则默认折叠\n      const total = r.models.length;\n      const needFold = total > 12;\n      const chipsClass = needFold ? 'chips collapsed' : 'chips';\n      const toggleHtml = needFold\n        ? `<span class=\"chipToggle\" data-e=\"${id}\">▾ 展开剩余 ${total - 12} 个模型（共 ${total} 个）</span>`\n        : (total > 5 ? `<span class=\"chipToggle\" data-e=\"${id}\" style=\"color:var(--muted)\">共 ${total} 个模型</span>` : '');\n      chips='<div class=\"'+chipsClass+'\" id=\"chips-'+id+'\">'+r.models.map(m=>{\n        const ms=r.modelStatus&&r.modelStatus[m];\n        const st=ms?`<span class=\"st\">${ms.ok?'✅':(ms.ok===false?'❌':'')}</span>`:'';\n        const title=ms&&ms.text?` title=\"${esc(ms.text)} ｜ 点击：测试+复制+填入模型ID输入框\"`:' title=\"点击：测试+复制+填入模型ID输入框\"';\n        return `<span class=\"chip\" data-e=\"${id}\" data-m=\"${esc(m)}\"${title}>${esc(m)}${st}</span>`;\n      }).join('')+'</div>'+toggleHtml;\n    }\n    h+=`<div class=\"card\" id=\"card-${id}\">\n      <h3><span class=\"tag ${stClass}\">${stText}</span>\n        <code class=\"k\">${esc(maskKey(e.key))}</code>\n        <span class=\"tag ${r.vendor||'unknown'}\">${r.vendor||'?'}</span></h3>\n      <div class=\"msg\">${esc(r.message)}</div>\n      <div class=\"meta\">接口：${esc(e.base||'(未填)')}${r.latency!=null?(' ｜ 响应'+latencyWord(r.latency)+'（'+r.latency+'ms）'):''}</div>\n      ${chips}\n      ${freeProbeHtml(r)}\n    </div>`;\n  }\n  box.innerHTML=h;\n  // chip 点击：测试 + 复制 + 设置到对应行的模型ID输入框\n  box.querySelectorAll('.chip').forEach(ch=>{\n    ch.onclick=async ()=>{\n      const eid = ch.dataset.e, model = ch.dataset.m;\n      // 动作1：测试可用性（保留原行为）\n      testSingleModel(eid, model, ch);\n      // 动作2：复制模型ID到剪贴板\n      try{\n        if(navigator.clipboard && window.isSecureContext){\n          await navigator.clipboard.writeText(model);\n        } else {\n          // fallback：选中文本后 execCommand\n          const ta=document.createElement('textarea'); ta.value=model;\n          ta.style.position='fixed'; ta.style.opacity='0';\n          document.body.appendChild(ta); ta.select();\n          document.execCommand('copy'); document.body.removeChild(ta);\n        }\n        ch.classList.add('copied');\n        setTimeout(()=>ch.classList.remove('copied'), 1000);\n        toast('已复制：'+model);\n      }catch(err){\n        log('复制失败：'+err.message, 'warn');\n      }\n      // 动作3：把模型ID填入对应行的模型ID输入框（覆盖原值）\n      const modelInp = document.querySelector('input[data-f=\"model\"][data-id=\"'+eid+'\"]');\n      if(modelInp){\n        modelInp.value = model;\n        modelInp.dispatchEvent(new Event('input', {bubbles:true}));\n      }\n    };\n  });\n  // 折叠/展开按钮\n  box.querySelectorAll('.chipToggle').forEach(t=>{\n    t.onclick=()=>{\n      const eid=t.dataset.e;\n      const chipsEl = document.getElementById('chips-'+eid);\n      if(!chipsEl) return;\n      const expanded = !chipsEl.classList.contains('collapsed');\n      if(expanded){\n        chipsEl.classList.add('collapsed');\n        const total = chipsEl.querySelectorAll('.chip').length;\n        t.textContent = '▾ 展开剩余 ' + Math.max(0, total - 12) + ' 个模型（共 '+total+' 个）';\n      } else {\n        chipsEl.classList.remove('collapsed');\n        t.textContent = '▴ 折叠（共 '+chipsEl.querySelectorAll('.chip').length+' 个）';\n      }\n    };\n  });\n}\n\n/* ---------- 单条测试 ---------- */\nasync function testEntry(id, opts){\n  opts=opts||{};\n  const e=entries.find(x=>x.id===id); if(!e) return;\n  if(!results[id]) results[id]={status:'warn', vendor:'', models:[], message:'测试中…', latency:null, modelStatus:{}};\n  else results[id].message='测试中…';\n  renderResults();\n  const t0=Date.now();\n  const isFT=isFreetoken(e.base);\n  log(`测试开始：${maskKey(e.key)} ｜ 接口=${e.base} ｜ 模型=${e.model||'(列首/未指定)'} ｜ 代理=${corsLabel()}${isFT?' ｜ 将自动免费探测':''}`, 'info');\n  let res={ok:false};\n  try{ res=await fetchModels(e.base, e.key); }\n  catch(err){ res={ok:false, error:'network'}; }\n  const latency=Date.now()-t0;\n  const vendor = res.ok ? res.vendor : 'openai';\n  const models = res.ok ? res.models : [];\n  const testModel = e.model || (res.ok ? res.models[0] : null);\n  if(res.ok) log(`模型列表成功：${maskKey(e.key)} ｜ 厂商=${res.vendor} ｜ 模型数=${res.models.length} ｜ 列表耗时 ${latency}ms`, 'ok');\n  if(models.length) populateModelDatalist(e.id, models);\n\n  let finalStatus, finalMessage;\n  if(opts.modelsOnly){\n    if(res.ok){ finalStatus='ok'; finalMessage=`密钥有效，服务正常（共 ${models.length} 个模型）`; }\n    else { finalStatus='bad'; finalMessage=describeError(res); log(`测试失败：${maskKey(e.key)} ｜ ${describeError(res)} ｜ 耗时 ${latency}ms`,'err'); }\n  } else if(testModel){\n    const cr=await chatTest(e.base, e.key, vendor, testModel);\n    if(cr.ok){\n      const authNote=cr.auth?`（鉴权方式：${cr.auth}）`:'';\n      finalMessage=(res.ok?`密钥有效，服务正常（共 ${models.length} 个模型）；`:`密钥有效（该接口无 /models 列表，已直接对话测试）；`)+`模型「${testModel}」对话测试通过，返回：「${cr.text}」${authNote}`;\n      finalStatus='ok';\n      log(`对话测试通过：${maskKey(e.key)} ｜ 模型=${testModel} ｜ 鉴权=${cr.auth} ｜ 返回：「${cr.text}」`,'ok');\n    } else {\n      finalMessage=res.ok?`密钥有效但对话测试未通过：${cr.error}`:`连接/认证失败：${cr.error}`;\n      finalStatus='bad';\n      log(`对话测试未通过：${maskKey(e.key)} ｜ 模型=${testModel} ｜ ${cr.error}`,'err');\n    }\n  } else {\n    if(!res.ok){ finalStatus='bad'; finalMessage=describeError(res); log(`测试失败：${maskKey(e.key)} ｜ ${describeError(res)} ｜ 耗时 ${latency}ms`,'err'); }\n    else { finalStatus='ok'; finalMessage=`密钥有效，服务正常（共 ${models.length} 个模型）`; }\n  }\n  results[id]={status:finalStatus, vendor, models, message:finalMessage, latency, modelStatus:results[id].modelStatus||{}};\n  renderResults();\n\n  // 仅 freetokenfaucet.com：自动做 1→2→3 免费探测，其他站点跳过\n  if(isFT) await runFreetokenProbe(id, models);\n}\n\nasync function testSingleModel(id, model, chipEl){\n  const e=entries.find(x=>x.id===id); if(!e) return;\n  const r=results[id]; const vendor=r.vendor||'openai';\n  chipEl.style.opacity='.6';\n  log(`单模型测试：${maskKey(e.key)} ｜ 模型=${model} ｜ 厂商=${vendor}`, 'info');\n  const cr=await chatTest(e.base, e.key, vendor, model);\n  if(!r.modelStatus) r.modelStatus={};\n  r.modelStatus[model]={ok:cr.ok, text:cr.ok?cr.text:cr.error};\n  log(cr.ok?`单模型通过：${model} ｜ 返回：「${cr.text}」`:`单模型失败：${model} ｜ ${cr.error}`, cr.ok?'ok':'err');\n  renderResults();\n}\n\n/* ---------- 并发调度 ---------- */\nasync function runTests(selectedOnly, modelsOnly){\n  const ids=entries.filter(e=>!selectedOnly||e.selected).map(e=>e.id);\n  if(ids.length===0){ toast('请先勾选要测试的条目'); return; }\n  log(`开始测试：${ids.length} 条 ｜ 模式=${modelsOnly?'仅列表':'完整'} ｜ 代理=${corsLabel()}`, 'info');\n  let i=0;\n  async function worker(){ while(i<ids.length){ const id=ids[i++]; await testEntry(id,{modelsOnly}); } }\n  await Promise.all(Array.from({length:Math.min(4,ids.length)}, ()=>worker()));\n  toast('测试完成');\n  log('测试完成', 'ok');\n}\n\n/* ---------- 导出 ---------- */\nfunction buildExportData(){\n  const scope=$('expScope').value;\n  const full=$('expFullKey').checked;\n  const withModels=$('expModels').checked;\n  let list=entries.filter(e=>{\n    const r=results[e.id];\n    if(scope==='ok') return r && r.status==='ok';\n    return true;\n  });\n  return list.map(e=>{\n    const r=results[e.id]||{};\n    return {\n      base:e.base, vendor:r.vendor||'', key: full? e.key : maskKey(e.key),\n      models: withModels? (r.models||[]) : [],\n      status: r.status==='ok'?'可用':(r.status==='warn'?'异常':'不可用'),\n      note: r.message||''\n    };\n  });\n}\nfunction exportMarkdown(data){\n  let md='## 大模型 Key 可用性清单\\n\\n';\n  md+='| 接口地址 | 厂商 | API Key | 可用模型 | 状态 | 备注 |\\n';\n  md+='|---|---|---|---|---|---|\\n';\n  for(const d of data){\n    const models=d.models.length?d.models.join(', '):'—';\n    md+=`| ${d.base||'—'} | ${d.vendor||'—'} | ${d.key} | ${models} | ${d.status} | ${d.note.replace(/\\|/g,'/')} |\\n`;\n  }\n  return md;\n}\nfunction renderExportPreview(){\n  const data=buildExportData();\n  const box=$('exportPreview');\n  if(data.length===0){ box.innerHTML='<div class=\"empty\">没有可导出的条目（先用「测试全部」）</div>'; return; }\n  let h='<table><thead><tr><th>接口地址</th><th>厂商</th><th>API Key</th><th>可用模型</th><th>状态</th><th>备注</th></tr></thead><tbody>';\n  for(const d of data){\n    const models=d.models.length?d.models.join(', '):'—';\n    const stc=d.status==='可用'?'ok':(d.status==='异常'?'warn':'bad');\n    h+=`<tr><td><code>${esc(d.base||'—')}</code></td><td>${esc(d.vendor||'—')}</td>\n      <td><code>${esc(d.key)}</code></td><td>${esc(models)}</td>\n      <td><span class=\"tag ${stc}\">${esc(d.status)}</span></td><td>${esc(d.note)}</td></tr>`;\n  }\n  h+='</tbody></table>';\n  box.innerHTML=h;\n}\nfunction download(name, content, type){\n  const blob=new Blob([content],{type}); const a=document.createElement('a');\n  a.href=URL.createObjectURL(blob); a.download=name; a.click();\n  setTimeout(()=>URL.revokeObjectURL(a.href),1000);\n}\n\n/* ---------- 网页持续对话 ---------- */\nconst chatSessions={}; // id -> {messages:[{role,content}], model}\nlet activeChatId=null;\n\n// 核心：携带完整历史调用对话接口（与 chatTest 共用鉴权尝试逻辑，但返回完整文本、支持任意 messages）\nasync function chatComplete(base, key, vendor, model, messages, maxTokens){\n  const url=chatUrl(base, vendor);\n  const isWeixin=(()=>{ try{ return new URL(base).hostname.toLowerCase().endsWith('weixin.qq.com'); }catch(e){ return false; } })();\n  // 微信等国产 OpenAI 兼容网关要求补 stream/temperature/user 三字段，否则 412\n  const body = vendor==='anthropic'\n    ? {model, max_tokens:maxTokens, messages}\n    : isWeixin\n      ? {model, messages, max_tokens:maxTokens, stream:false, temperature:0.7, user:'llm-tester'}\n      : {model, messages, max_tokens:maxTokens};\n  const bodyStr=JSON.stringify(body);\n  const variants=[];\n  if(isWeixin){\n    variants.push({name:'X-OPENAI-TOKEN', h:{'X-OPENAI-TOKEN':key,'Content-Type':'application/json'}});\n    variants.push({name:'X-APPID', h:{'X-APPID':key,'Content-Type':'application/json'}});\n    variants.push({name:'X-Api-Key', h:{'X-Api-Key':key,'Content-Type':'application/json'}});\n    variants.push({name:'Api-Key', h:{'Api-Key':key,'Content-Type':'application/json'}});\n    variants.push({name:'X-Org-Id+Bearer', h:{'Authorization':'Bearer '+key,'X-Org-Id':key,'Content-Type':'application/json'}});\n    variants.push({name:'X-User-Id+Bearer', h:{'Authorization':'Bearer '+key,'X-User-Id':key,'Content-Type':'application/json'}});\n    variants.push({name:'token-prefix', h:{'Authorization':'token '+key,'Content-Type':'application/json'}});\n    variants.push({name:'?key=query', h:{'Authorization':'Bearer '+key,'Content-Type':'application/json'}, urlSuffix:'?key='+encodeURIComponent(key)});\n    variants.push({name:'?token=query', h:{'Authorization':'Bearer '+key,'Content-Type':'application/json'}, urlSuffix:'?token='+encodeURIComponent(key)});\n  }\n  variants.push({name:'Bearer', h:{'Authorization':'Bearer '+key,'Content-Type':'application/json'}});\n  if(vendor==='anthropic') variants.push({name:'x-api-key', h:{'x-api-key':key,'anthropic-version':'2023-06-01','Content-Type':'application/json'}});\n  const tried=[];\n  for(const v of variants){\n    try{\n      const vUrl = v.urlSuffix ? (url+v.urlSuffix) : url;\n      const r=await compatFetch(proxyWrap(vUrl),{method:'POST',headers:v.h,body:bodyStr}, 60000);\n      if(r.ok){\n        const j=await r.json().catch(()=>null);\n        let text='';\n        if(vendor==='anthropic') text=(j.content&&j.content[0]&&j.content[0].text)||'';\n        else text=(j.choices&&j.choices[0]&&j.choices[0].message&&j.choices[0].message.content)||'';\n        return {ok:true, text, auth:v.name, tried};\n      }\n      tried.push({name:v.name, error:humanStatus(r.status)});\n    }catch(e){ tried.push({name:v.name, error:e.name==='AbortError'?'响应超时（>60s，模型可能在思考或服务慢）':'网络/跨域错误'}); }\n  }\n  const detail=tried.map(t=>`${t.name}→${t.error}`).join('；');\n  return {ok:false, error:detail, tried};\n}\n\n// 待发送的附件缓存：openChat 时创建，每次发送后清空\nlet chatPendingFiles=[];\n\n// 文件读取 → {name,type,size,dataUrl}\nfunction readFileAsDataURL(file){\n  return new Promise((resolve,reject)=>{\n    const r=new FileReader();\n    r.onload=()=>resolve({name:file.name, type:file.type||'application/octet-stream', size:file.size, dataUrl:r.result});\n    r.onerror=()=>reject(r.error);\n    r.readAsDataURL(file);\n  });\n}\n\n// 把文件名+大小渲染成 chip\nfunction renderFileChips(){\n  const box=$('fileChips'); if(!box) return;\n  if(!chatPendingFiles.length){ box.innerHTML=''; return; }\n  box.innerHTML = chatPendingFiles.map((f,i)=>{\n    const isImg = (f.type||'').startsWith('image/');\n    const thumb = isImg ? `<img src=\"${f.dataUrl}\" alt=\"\">` : `<span>📄</span>`;\n    const sz = f.size<1024 ? f.size+'B' : f.size<1048576 ? (f.size/1024).toFixed(1)+'KB' : (f.size/1048576).toFixed(2)+'MB';\n    return `<span class=\"file-chip\" data-i=\"${i}\">${thumb}<span>${esc(f.name)} <span style=\"color:var(--muted);\">(${sz})</span></span><span class=\"x\" title=\"移除\">⨯</span></span>`;\n  }).join('');\n  box.querySelectorAll('.file-chip').forEach(ch=>{\n    const i=+ch.dataset.i;\n    ch.querySelector('.x').onclick=()=>{ chatPendingFiles.splice(i,1); renderFileChips(); updateFileInfo(); };\n  });\n  $('chatFileInfo').textContent = `已选 ${chatPendingFiles.length} 个文件`;\n}\nfunction updateFileInfo(){\n  $('chatFileInfo').textContent = chatPendingFiles.length ? `已选 ${chatPendingFiles.length} 个文件` : '未选择文件';\n}\n\n// 根据文件 mime 决定如何作为消息内容块（图片用 image_url，其他标记为附件文本块）\nfunction buildContentFromFiles(files, fallbackText){\n  const blocks=[];\n  if(fallbackText && fallbackText.trim()) blocks.push({type:'text', text:fallbackText});\n  for(const f of files){\n    if((f.type||'').startsWith('image/')){\n      blocks.push({type:'image_url', image_url:{url:f.dataUrl}});\n      blocks.push({type:'text', text:`(图片附件：${f.name})`});\n    } else {\n      // 非图片：作为\"附件\"标记，告知模型文件已附加并附上文件名/mime\n      blocks.push({type:'text', text:`[已附加文件：${f.name}（${f.type||'application/octet-stream'}，${f.size<1024?f.size+'B':(f.size/1024).toFixed(1)+'KB'}）——本前端无法直接上传到模型上下文；如需模型读取请在外部转写后粘到下方文本框]`});\n    }\n  }\n  return blocks;\n}\n\nfunction openChat(id){\n  const e=entries.find(x=>x.id===id); if(!e) return;\n  activeChatId=id;\n  const r=results[id];\n  const defModel=e.model || (r&&r.models&&r.models[0]) || '';\n  if(!chatSessions[id]) chatSessions[id]={messages:[], model:defModel};\n\n  // 关闭任何已打开的聊天面板（同时只保留一个）\n  $('chatHost').innerHTML='';\n\n  // 注入内嵌面板到 chatHost\n  const tpl=$('chatTpl');\n  const node=tpl.content.firstElementChild.cloneNode(true);\n  $('chatHost').appendChild(node);\n\n  const cm = $('chatModel'), meta = $('chatMeta');\n  // 优先取当前行模型输入框的实时值（chip 点击后已更新），其次旧会话缓存，最后默认模型\n  const domModel = (document.querySelector('input[data-f=\"model\"][data-id=\"'+id+'\"]')||{}).value || '';\n  cm.value = domModel || (chatSessions[id]&&chatSessions[id].model) || defModel || '';\n\n  meta.innerHTML=`接口：${esc(e.base||'(未填)')} ｜ Key：${esc(maskKey(e.key))} ｜ 厂商=${(r&&r.vendor)||'auto'} ｜ 代理=${corsLabel()}` +\n    ` <span style=\"margin-left:8px;color:var(--muted);\">↳ 此对话窗口会保留在本页面下方；点击其他\"对话\"按钮可切换凭据</span>`;\n\n  chatPendingFiles=[];\n  renderFileChips();\n  updateFileInfo();\n\n  // 滚动管理：用户手动上滚时显示「回到底部」按钮\n  const body = $('chatBody');\n  const scrollBtn = $('scrollBottomBtn');\n  let isAutoScroll = true; // 默认自动滚动到底部\n  if (body) {\n    body.addEventListener('scroll', () => {\n      const nearBottom = body.scrollHeight - body.scrollTop - body.clientHeight < 60;\n      isAutoScroll = nearBottom;\n      if (scrollBtn) scrollBtn.classList.toggle('show', !nearBottom);\n    });\n  }\n  if (scrollBtn) {\n    scrollBtn.onclick = () => {\n      if (body) body.scrollTo({ top: body.scrollHeight, behavior: 'smooth' });\n      isAutoScroll = true;\n      scrollBtn.classList.remove('show');\n    };\n  }\n\n  // 事件绑定\n  $('chatClose').onclick=()=>{\n    $('chatHost').innerHTML='';\n    activeChatId=null;\n  };\n  $('chatSend').onclick=sendChat;\n  $('chatText').onkeydown=(ev)=>{\n    if(ev.key==='Enter' && !ev.shiftKey){ ev.preventDefault(); sendChat(); }\n  };\n  $('chatFile').onchange=async (ev)=>{\n    const arr=Array.from(ev.target.files||[]);\n    // 限制总大小 ≤ 10MB，避免巨大文件导致请求超时\n    const MAX=10*1024*1024;\n    for(const f of arr){\n      if(f.size>MAX){ toast(`已跳过 ${f.name}（大于 10MB）`); continue; }\n      try{ const d=await readFileAsDataURL(f); chatPendingFiles.push(d); }\n      catch(err){ toast(`读取失败：${f.name}`); }\n    }\n    renderFileChips(); updateFileInfo();\n    ev.target.value=''; // 允许重复选相同文件\n  };\n\n  renderChatBody(id);\n  cm.oninput=()=>{ chatSessions[id].model=cm.value.trim(); };\n  $('chatText').focus();\n  $('chatStatus').textContent='已就绪';\n}\n\nfunction renderChatBody(id, scrollIfAtBottom=true){\n  const s=chatSessions[id]; const box=$('chatBody');\n  if(!box) return;\n  if(!s||s.messages.length===0){ box.innerHTML='<div class=\"empty\">开始对话吧。下方输入消息，回车发送，Shift+Enter 换行。可点 <b>📎 上传文件</b> 附加图片/文档（图片会作为 image_url 发送）。</div>'; box.scrollTop=box.scrollHeight; return; }\n  // content 可能是字符串或数组（携带文件）\n  box.innerHTML=s.messages.map((m, idx)=>{\n    let inner='';\n    const c=m.content;\n    if(typeof c === 'string'){\n      inner = esc(c);\n    } else if(Array.isArray(c)){\n      inner = c.map(b=>{\n        if(b.type==='text') return esc(b.text||'');\n        if(b.type==='image_url' && b.image_url && b.image_url.url){\n          return `<img src=\"${esc(b.image_url.url)}\" alt=\"image\">`;\n        }\n        return '';\n      }).filter(Boolean).join('<br>');\n    }\n    // 提取纯文本用于复制\n    const plainText = extractChatPlain(m.content);\n    return `<div class=\"chat-msg ${m.role}\">\n      <div class=\"chat-bubble\">\n        ${inner||'<i>(空)</i>'}\n        <button class=\"chat-copy-btn\" data-idx=\"${idx}\" data-role=\"${m.role}\" title=\"复制这条消息\">📋</button>\n      </div>\n    </div>`;\n  }).join('');\n  // 绑定复制按钮事件\n  box.querySelectorAll('.chat-copy-btn').forEach(btn=>{\n    btn.onclick=()=>copyChatMsg(btn.dataset.idx, btn.dataset.role);\n  });\n  if(scrollIfAtBottom) box.scrollTop=box.scrollHeight;\n}\n// 从 content（字符串或数组）中提取纯文本\nfunction extractChatPlain(content){\n  if(typeof content === 'string') return content;\n  if(Array.isArray(content)) return content.filter(b=>b.type==='text').map(b=>b.text).join('');\n  return '';\n}\nasync function copyChatMsg(idx, role){\n  const s=chatSessions[activeChatId]; if(!s) return;\n  const msg=s.messages[idx]; if(!msg) return;\n  const text=extractChatPlain(msg.content)||'(含图片附件)';\n  try{\n    await navigator.clipboard.writeText(text);\n  }catch(e){\n    // fallback\n    const ta=document.createElement('textarea'); ta.value=text; ta.style.position='fixed'; ta.style.opacity='0';\n    document.body.appendChild(ta); ta.select();\n    try{ document.execCommand('copy'); }catch(err){}\n    document.body.removeChild(ta);\n  }\n  // 视觉反馈\n  const btn=document.querySelector(`.chat-copy-btn[data-idx=\"${idx}\"][data-role=\"${role}\"]`);\n  if(btn){\n    btn.textContent='✓'; btn.classList.add('copied');\n    setTimeout(()=>{ btn.textContent='📋'; btn.classList.remove('copied'); }, 1200);\n  }\n  toast('已复制'+(role==='user'?'提问':'答复'));\n}\n\nasync function sendChat(){\n  const id=activeChatId; if(!id) return;\n  const s=chatSessions[id];\n  const e=entries.find(x=>x.id===id); if(!e) return;\n  const text=($('chatText').value||'').trim();\n  const files = chatPendingFiles.slice();\n  if(!text && !files.length){ toast('请输入消息或选择文件'); return; }\n  const model=($('chatModel').value||'').trim();\n  if(!model){ toast('请填写模型ID'); return; }\n  s.model=model;\n\n  // 构造 content：字符串或数组\n  let content;\n  if(files.length){\n    content = buildContentFromFiles(files, text);\n  } else {\n    content = text;\n  }\n  s.messages.push({role:'user', content});\n  $('chatText').value='';\n  chatPendingFiles=[]; renderFileChips(); updateFileInfo();\n  renderChatBody(id);\n\n  const box=$('chatBody');\n  const think=document.createElement('div'); think.className='chat-msg assistant';\n  think.innerHTML='<div class=\"chat-bubble thinking\">思考中…</div>'; box.appendChild(think); box.scrollTop=box.scrollHeight;\n  $('chatStatus').textContent='模型思考中…';\n  const startTs=Date.now();\n  const vendor=(results[id]&&results[id].vendor)||'openai';\n  const cr=await chatComplete(e.base, e.key, vendor, model, s.messages, 1024);\n  const ms=Date.now()-startTs;\n  if(cr.ok){\n    s.messages.push({role:'assistant', content:cr.text});\n    renderChatBody(id);\n    $('chatStatus').textContent=`完成 · ${ms}ms · 鉴权=${cr.auth}`;\n    log(`对话(持续)：${maskKey(e.key)} ｜ 模型=${model} ｜ 鉴权=${cr.auth} ｜ 用户：「${text||'(含附件)'}」`, 'ok');\n  } else {\n    think.querySelector('.chat-bubble').textContent='❌ 失败：'+cr.error;\n    think.querySelector('.chat-bubble').classList.remove('thinking');\n    renderChatBody(id);\n    $('chatStatus').textContent=`失败 · ${ms}ms`;\n    log(`对话(持续)失败：${maskKey(e.key)} ｜ 模型=${model} ｜ ${cr.error}`, 'err');\n  }\n}\n\n/* ---------- 事件 ---------- */\nfunction doParse(){\n  const text=$('input').value;\n  entries=parseInput(text);\n  for(const k in results) delete results[k];\n  renderTable();\n  $('parseHint').textContent = entries.length\n    ? `已识别 ${entries.length} 组凭据，默认全部勾选。可修改后测试。`\n    : '未识别到 Key，请检查粘贴内容（需含 sk-/sk-ant-/AIza/tf_ 等格式密钥）。';\n  if(entries.length){\n    toast('解析完成：'+entries.length+' 组');\n    log('解析完成，共 '+entries.length+' 组凭据', 'info');\n    entries.forEach(e=>log(`· 接口=${e.base||'(未填)'} ｜ Key=${maskKey(e.key)} ｜ 模型=${e.model||'(待列表)'}`, 'info'));\n  } else {\n    log('解析失败：未识别到有效密钥', 'warn');\n  }\n}\n\n$('parseBtn').onclick=doParse;\n$('input').addEventListener('input', ()=>{ clearTimeout(window.__pt); window.__pt=setTimeout(doParse,500); });\n$('selAll').onclick=()=>{ entries.forEach(e=>e.selected=true); renderTable(); };\n$('selNone').onclick=()=>{ entries.forEach(e=>e.selected=false); renderTable(); };\n$('testAll').onclick=()=>runTests(false,false);\n$('testSel').onclick=()=>runTests(true,false);\n$('testList').onclick=()=>runTests(false,true);\n$('clearBtn').onclick=()=>{ entries=[]; for(const k in results) delete results[k]; $('input').value=''; renderTable(); $('results').innerHTML='<div class=\"empty\">尚无测试结果</div>'; $('parseHint').textContent='粘贴后自动解析。'; };\n\n/* CORS 方案选择（四选一，单选） */\ndocument.querySelectorAll('input[name=corsMethod]').forEach(r=>r.onchange=()=>{\n  corsMethod=r.value;\n  if(corsMethod==='D' && !proxyDeploy) proxyDeploy='local';\n  if(corsMethod==='D' && proxyDeploy==='local') proxyBase='http://localhost:8787';\n  renderCorsDetail();\n  if(corsMethod==='D') checkProxy();\n  else { const st=$('corsStatus'); if(st){ st.textContent=''; st.className='proxyState'; } }\n  log('已选择 CORS 方案：'+corsMethod+'（'+corsLabel()+'）', 'info');\n});\nrenderCorsDetail();\nsetCorsCollapsed(corsCollapsed);    // 应用折叠状态\n$('corsHead').onclick=()=>setCorsCollapsed(!corsCollapsed);\n\n$('logCopy').onclick=()=>{\n  const txt=logLines.join('\\n')||'（无日志）';\n  navigator.clipboard.writeText(txt).then(()=>toast('日志已复制')).catch(()=>{\n    const ta=document.createElement('textarea'); ta.value=txt; document.body.appendChild(ta); ta.select();\n    try{ document.execCommand('copy'); toast('日志已复制'); }catch(e){ toast('复制失败，请手动选择'); }\n    ta.remove();\n  });\n};\n$('logClear').onclick=()=>{ logLines.length=0; $('logBox').innerHTML='<div class=\"empty\">暂无日志（解析或测试时自动记录）</div>'; };\n\n$('exportBtn').onclick=()=>{ renderExportPreview(); $('exportOverlay').classList.add('show'); };\n$('closeExport').onclick=()=>$('exportOverlay').classList.remove('show');\n$('expScope').onchange=renderExportPreview;\n$('expFullKey').onchange=renderExportPreview;\n$('expModels').onchange=renderExportPreview;\n$('copyMd').onclick=()=>{ navigator.clipboard.writeText(exportMarkdown(buildExportData())).then(()=>toast('已复制 Markdown')); };\n$('dlMd').onclick=()=>download('llm-keys.md', exportMarkdown(buildExportData()), 'text/markdown');\n$('dlJson').onclick=()=>download('llm-keys.json', JSON.stringify(buildExportData(),null,2), 'application/json');\n$('dlTxt').onclick=()=>{\n  const d=buildExportData();\n  const t=d.map(x=>`接口:${x.base}\\n厂商:${x.vendor}\\nKey:${x.key}\\n模型:${x.models.join(', ')}\\n状态:${x.status}\\n备注:${x.note}\\n${'-'.repeat(30)}`).join('\\n');\n  download('llm-keys.txt', t, 'text/plain');\n};\n\n/* 主题切换 */\nfunction applyTheme(mode){\n  document.body.className = mode==='light'?'light':'dark';\n  $('themeBtn').textContent = mode==='light'?'☀️ 亮色':'🌙 暗色';\n  try{ localStorage.setItem('llmTesterTheme', mode); }catch(e){}\n}\n$('themeBtn').onclick=()=>applyTheme(document.body.className==='light'?'dark':'light');\ntry{ const m=localStorage.getItem('llmTesterTheme'); if(m) applyTheme(m); }catch(e){}\n\n/* 对话面板事件已移至 openChat 内（每次面板创建时绑定） */\nrenderTable();\n</script>\n</body>\n</html>\n";
